example.code:
path "secret/data/payments/*" {
  capabilities = ["read", "list"]
}
path "secret/metadata/payments/*" {
  capabilities = ["list"]
}

path "pki/issue/web" {
  capabilities = ["create", "update"]
  allowed_parameters = { "common_name" = ["*.example.com"] }
}

path "secret/data/user/{{identity.entity.name}}/*" {
  capabilities = ["create", "read", "update", "delete", "list"]
}

# Sentinel EGP: require MFA context on admin paths
import "time"
main = rule { request.auth.metadata.mfa_validated == "true" }

# integrated storage: no external backend to operate
storage "raft" {
  path = "/vault/data"
  node_id = "node-1"
}

{{ with secret "pki_int/issue/web" "common_name=app.example.com" }}
{{ .Data.certificate }}{{ end }}
# consul-template -template "cert.tpl:/etc/ssl/app.crt:nginx -s reload"

# connect CA config pointing at Vault PKI
{
  "provider": "vault",
  "config": { "address": "https://vault:8200",
    "intermediate_pki_path": "pki_int/connect" }
}

storage "raft" {
  path    = "/vault/data"
  node_id = "vault-1"
}
cluster_addr = "https://vault-1:8201"

storage "raft" {
  path = "/vault/data"
  node_id = "vault-1"
  snapshot_threshold = 8192
}

{
  "service": { "name": "orders",
    "connect": { "sidecar_service": {
      "proxy": { "upstreams": [{ "destination_name": "payments", "local_bind_port": 5000 }] }}}}}

